import crypto from 'node:crypto';

/**
 * PURE HELPERS SHARED BY EVERY DATABASE QUERY
 * ------------------------------------------
 * The app deliberately keeps its SQL portable between SQLite (used for local
 * development, zero setup) and PostgreSQL (used in production, e.g. Supabase).
 *
 * To make one schema work on both engines we follow three simple rules:
 *   1. Every primary key is a TEXT id generated by the app (crypto.randomUUID).
 *   2. Every timestamp is stored as a TEXT ISO-8601 string (sorts correctly).
 *   3. Date maths is done in JavaScript, never in SQL.
 */

export function newId(): string {
  return crypto.randomUUID();
}

export function nowIso(): string {
  return new Date().toISOString();
}

/** A random, human-friendly friend code such as "ABC123". */
export function newFriendCode(): string {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no confusing 0/O/1/I
  let code = '';
  const bytes = crypto.randomBytes(6);
  for (let i = 0; i < 6; i += 1) {
    code += alphabet[bytes[i] % alphabet.length];
  }
  return code;
}

/** SQLite returns numbers for SUM(); PostgreSQL returns bigint strings. */
export function num(value: unknown, fallback = 0): number {
  if (value === null || value === undefined) return fallback;
  const parsed = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export function bool(value: unknown): boolean {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;
  if (typeof value === 'string') return value === '1' || value.toLowerCase() === 'true';
  return false;
}

// ---------------------------------------------------------------------------
// Dates. All "day" keys are local-calendar dates in YYYY-MM-DD form because a
// user's "today" is their own calendar day, not UTC's.
// ---------------------------------------------------------------------------

export function toDayKey(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

export function todayKey(): string {
  return toDayKey(new Date());
}

/** Returns a new Date shifted by `days` (can be negative). */
export function addDays(date: Date, days: number): Date {
  const copy = new Date(date.getTime());
  copy.setDate(copy.getDate() + days);
  return copy;
}

export function dayKeyOffset(days: number): string {
  return toDayKey(addDays(new Date(), days));
}

/** Inclusive list of day keys ending today, e.g. last 14 days. */
export function recentDayKeys(count: number): string[] {
  const keys: string[] = [];
  for (let i = count - 1; i >= 0; i -= 1) {
    keys.push(dayKeyOffset(-i));
  }
  return keys;
}

/** ISO week start (Monday) as a day key. */
export function startOfWeekKey(): string {
  const d = new Date();
  const day = (d.getDay() + 6) % 7; // 0 = Monday
  return toDayKey(addDays(d, -day));
}

export function startOfMonthKey(): string {
  const d = new Date();
  return toDayKey(new Date(d.getFullYear(), d.getMonth(), 1));
}
